// A deliverable entry (form).
//
// Represents a single deliverable item within any deliverable category.
// Captures identification, delivery logistics, quality requirements,
// ownership, and acceptance linkage.
export class DeliverableEntry extends SomNode {
  constructor(doc: SpecDocument, path: string) {
    super(doc, path);
  }

  get content(): DeliverableEntryContentForm {
    return new DeliverableEntryContentForm(this.doc, this.path + "/content");
  }

  // Identification details.
  get identity(): DeliverableEntryIdentityForm {
    return new DeliverableEntryIdentityForm(this.doc, this.path + "/DLVID");
  }

  // Delivery logistics.
  get logistics(): DeliverableEntryLogisticsForm {
    return new DeliverableEntryLogisticsForm(this.doc, this.path + "/DLVLOG");
  }

  // Version and compatibility.
  get version(): DeliverableEntryVersionForm {
    return new DeliverableEntryVersionForm(this.doc, this.path + "/DLVVR");
  }

  // Quality and acceptance.
  get quality(): DeliverableEntryQualityForm {
    return new DeliverableEntryQualityForm(this.doc, this.path + "/DLVQL");
  }

  // Ownership and responsibility.
  get ownership(): DeliverableEntryOwnershipForm {
    return new DeliverableEntryOwnershipForm(this.doc, this.path + "/DLVOW");
  }

  // Dependencies.
  get dependencies(): SomList<DeliverableDependencies> {
    return new SomList(this.doc, this.path + "/DLVDP-DEPE-LST", (d: SpecDocument, p: string) => new DeliverableDependencies(d, p), "DLVDP-DEPE-xxx");
  }

  // Licensing and legal.
  get legal(): DeliverableEntryLegalForm {
    return new DeliverableEntryLegalForm(this.doc, this.path + "/DLVLG");
  }

  // Documentation.
  get documentation(): DeliverableEntryDocumentationForm {
    return new DeliverableEntryDocumentationForm(this.doc, this.path + "/DLVDC");
  }
}

