// SBP.1 Document Control.
//
// Holds the [DocumentHeader] (id, project, version, date, author, status)
// together with the document's revision history ([RevisionEntry] list) and
// the [ApprovalRecord]s that gate its release.
export class DocumentControl extends SomNode {
  constructor(doc: SpecDocument, path: string) {
    super(doc, path);
  }

  get canHaveContent(): boolean {
    return true;
  }

  get content(): string {
    return this.doc.content(this.path + "/content") || '';
  }

  set content(value: string) {
    this.doc.setContent(this.path + "/content", value);
  }

  // Document header form (id, project, version, date, author, status).
  get header(): DocumentHeader {
    return new DocumentHeader(this.doc, this.path + "/header");
  }

  // Chronological revision history of this document.
  get revisionHistory(): SomList<RevisionEntry> {
    return new SomList(this.doc, this.path + "/RVENT-REVS-LST", (d: SpecDocument, p: string) => new RevisionEntry(d, p), "RVENT-REVS-xxx");
  }

  // Formal approvals (sign-offs) recorded for this document.
  get approvals(): SomList<ApprovalRecord> {
    return new SomList(this.doc, this.path + "/APREC-APRV-LST", (d: SpecDocument, p: string) => new ApprovalRecord(d, p), "APREC-APRV-xxx");
  }

  // Reference documents — the catalogue of documents this specification draws
  // on (standards, policies, regulations, related specs). They live here
  // because referenced documents are ISO/IEC/IEEE 29148 §6 front matter and
  // belong with document control.
  get referenceDocuments(): ReferenceDocuments {
    return new ReferenceDocuments(this.doc, this.path + "/referenceDocuments");
  }
}

