// An interaction entry.
//
// Comprehensive interaction definition following Cockburn's fully dressed
// use case template. Seeds the ISC (Interaction Scenarios) document.
export class InteractionEntry extends SomNode {
  constructor(doc: SpecDocument, path: string) {
    super(doc, path);
  }

  // Interaction identification (use case header).
  get identification(): InteractionEntryIdentificationForm {
    return new InteractionEntryIdentificationForm(this.doc, this.path + "/INID");
  }

  // Use case scope and context (Cockburn style).
  get scopeContext(): InteractionEntryScopeContextForm {
    return new InteractionEntryScopeContextForm(this.doc, this.path + "/UCSC");
  }

  // Stakeholders and interests.
  get stakeholders(): SomList<StakeholdersAndInterests> {
    return new SomList(this.doc, this.path + "/STANIN-STAK-LST", (d: SpecDocument, p: string) => new StakeholdersAndInterests(d, p), "STANIN-STAK-xxx");
  }

  // Preconditions and triggers.
  get preconditions(): SomList<PreconditionsAndTriggers> {
    return new SomList(this.doc, this.path + "/PRANTR-PREC-LST", (d: SpecDocument, p: string) => new PreconditionsAndTriggers(d, p), "PRANTR-PREC-xxx");
  }

  // Postconditions and guarantees.
  get postconditions(): SomList<PostconditionsAndGuarantees> {
    return new SomList(this.doc, this.path + "/POANGU-POST-LST", (d: SpecDocument, p: string) => new PostconditionsAndGuarantees(d, p), "POANGU-POST-xxx");
  }

  // Main success scenario (basic flow).
  get mainScenario(): MainSuccessScenario {
    return new MainSuccessScenario(this.doc, this.path + "/mainScenario");
  }

  // Extensions (alternative and exception flows).
  get extensions(): UseCaseExtensions {
    return new UseCaseExtensions(this.doc, this.path + "/extensions");
  }

  // Technology and data variations.
  get variations(): SomList<TechnologyDataVariations> {
    return new SomList(this.doc, this.path + "/TEDAVA-VARI-LST", (d: SpecDocument, p: string) => new TechnologyDataVariations(d, p), "TEDAVA-VARI-xxx");
  }

  // UI requirements preview.
  get uiPreview(): UIRequirementsPreview {
    return new UIRequirementsPreview(this.doc, this.path + "/uiPreview");
  }

  // Performance and frequency.
  get performance(): InteractionEntryPerformanceForm {
    return new InteractionEntryPerformanceForm(this.doc, this.path + "/INPE");
  }

  // Security and authorization.
  get security(): InteractionEntrySecurityForm {
    return new InteractionEntrySecurityForm(this.doc, this.path + "/INSE");
  }

  // Business rules triggered.
  get businessRules(): SomList<InteractionBusinessRules> {
    return new SomList(this.doc, this.path + "/INBURU-BUSI-LST", (d: SpecDocument, p: string) => new InteractionBusinessRules(d, p), "INBURU-BUSI-xxx");
  }

  // Related elements and traceability.
  get traceability(): InteractionEntryTraceabilityForm {
    return new InteractionEntryTraceabilityForm(this.doc, this.path + "/INTR");
  }
}

