// A screen element entry (form).
//
// Any interactive or display element within a screen section: buttons, fields,
// data displays, icons, labels, status indicators.
export class ScreenElementEntry extends SomNode {
  constructor(doc: SpecDocument, path: string) {
    super(doc, path);
  }

  get content(): ScreenElementEntryContentForm {
    return new ScreenElementEntryContentForm(this.doc, this.path + "/content");
  }

  // Labels and icon resources.
  get resources(): ScreenElementEntryResourcesForm {
    return new ScreenElementEntryResourcesForm(this.doc, this.path + "/SEER");
  }

  // Placement and layout settings.
  get layout(): ScreenElementEntryLayoutForm {
    return new ScreenElementEntryLayoutForm(this.doc, this.path + "/SCELENLA");
  }

  // Visibility and enablement rules.
  //
  // These are *business* conditions on an element the caller is already
  // authorized for. Who may see or use it at all is [access].
  get behavior(): ScreenElementEntryBehaviorForm {
    return new ScreenElementEntryBehaviorForm(this.doc, this.path + "/SEEB");
  }

  // Access control — what a caller must satisfy to see or use this element.
  //
  // The shared CE-AZ requirement section (`AZREQ`). An element whose access
  // has degrees — hidden, locked, read-only, interactive — authors the Graded
  // kind, which is what the old free-text permission-effect field was trying
  // to say.
  get access(): AuthorizationRequirementSpec {
    return new AuthorizationRequirementSpec(this.doc, this.path + "/access");
  }

  // Styling and data binding.
  get presentation(): ScreenElementEntryPresentationForm {
    return new ScreenElementEntryPresentationForm(this.doc, this.path + "/SCELENPR");
  }

  // 10.2.1.n.m.k.1. Element Action.
  //
  // Present only for action-kind elements (`@OneOf` case, csmb6).
  get elementAction(): ScreenElementAction {
    return new ScreenElementAction(this.doc, this.path + "/elementAction");
  }

  // 10.2.1.n.m.k.2. Element Field Spec.
  //
  // Present only for input-kind elements (`@OneOf` case, csmb6).
  get fieldSpec(): ScreenElementFieldSpec {
    return new ScreenElementFieldSpec(this.doc, this.path + "/fieldSpec");
  }

  // 10.2.1.n.m.k.3. Element Data Display.
  //
  // Present only for display-kind elements (`@OneOf` case, csmb6).
  get dataDisplay(): ScreenElementDataDisplay {
    return new ScreenElementDataDisplay(this.doc, this.path + "/dataDisplay");
  }

  // Contains 0+× ElementValidationRule.
  get validationRules(): SomList<ElementValidationRuleEntry> {
    return new SomList(this.doc, this.path + "/ELVARU-VALI-LST", (d: SpecDocument, p: string) => new ElementValidationRuleEntry(d, p), "ELVARU-VALI-xxx");
  }
}

// Field specification for an input-type element (form).
//
// Defines input behavior: data type, constraints, validation trigger, masks.
export class ScreenElementFieldSpec extends SomNode {
  constructor(doc: SpecDocument, path: string) {
    super(doc, path);
  }

  get content(): ScreenElementFieldSpecContentForm {
    return new ScreenElementFieldSpecContentForm(this.doc, this.path + "/content");
  }

  // Prefix, suffix, and formatting.
  get formatting(): ScreenElementFieldSpecFormattingForm {
    return new ScreenElementFieldSpecFormattingForm(this.doc, this.path + "/SEFSF");
  }

  // Number-kind options — a promoted `@OneOf` case (csmb6).
  //
  // Present only for numeric field kinds; carries only numeric constraints
  // (no length or option-source attributes).
  get numberOptions(): ScreenElementFieldSpecNumberOptionsForm {
    return new ScreenElementFieldSpecNumberOptionsForm(this.doc, this.path + "/SEFSN");
  }

  // Date-kind options — a promoted `@OneOf` case (csmb6).
  //
  // Present only for date/time field kinds; carries only temporal
  // constraints (no numeric precision or length attributes).
  get dateOptions(): ScreenElementFieldSpecDateOptionsForm {
    return new ScreenElementFieldSpecDateOptionsForm(this.doc, this.path + "/SEFSD");
  }

  // Text-kind options — a promoted `@OneOf` case (csmb6).
  //
  // Present only for free-text field kinds; carries only length constraints.
  get textOptions(): ScreenElementFieldSpecTextOptionsForm {
    return new ScreenElementFieldSpecTextOptionsForm(this.doc, this.path + "/SEFST");
  }

  // Validation behavior.
  get validation(): ScreenElementFieldSpecValidationForm {
    return new ScreenElementFieldSpecValidationForm(this.doc, this.path + "/SEFSV");
  }

  // Select-kind options — a promoted `@OneOf` case (csmb6).
  //
  // Present only for the enumeration (select) field kind; carries only the
  // option-source and selection-mode attributes.
  get selectOptions(): ScreenElementFieldSpecSelectOptionsForm {
    return new ScreenElementFieldSpecSelectOptionsForm(this.doc, this.path + "/SEFSS");
  }

  // File-kind options — a promoted `@OneOf` case (csrb8).
  //
  // Present only for the file field kind; carries what may be chosen and how
  // the chosen file is shown. The **storage group** is deliberately absent: a
  // file's group is authored once on its CE-DB file-reference column
  // (`codespecs_mapping.md` §5.13.1) and derived here, so the two can never
  // name different groups. So is a download affordance, which follows from the
  // field being wired for transfer and the file being stored (§5.18).
  get fileOptions(): ScreenElementFieldSpecFileOptionsForm {
    return new ScreenElementFieldSpecFileOptionsForm(this.doc, this.path + "/SEFSU");
  }
}

